using System.Windows;using System.Windows.Controls;using System.Windows.Media;using System.Windows.Shapes;using DeskCanvas.App.Services;using DeskCanvas.Core;
namespace DeskCanvas.App.Windows;
internal sealed class SystemMonitorItemContent:IDesktopItemContent{
 private readonly CanvasItem item;private readonly ISystemMetricsService service;private readonly Border root=new(){ClipToBounds=true,CornerRadius=new CornerRadius(25),BorderThickness=new Thickness(1)};private readonly Grid panel=new();private readonly TextBlock header=new(){Text="SYSTEM STATUS",FontWeight=FontWeights.SemiBold};private readonly Row[] metrics={new("CPU"),new("RAM"),new("GPU")};private readonly Row down=new("↓  DOWN"),up=new("↑  UP");private readonly Border divider=new(){Height=1};private IDisposable? lease;private bool active,initial=true;
 internal SystemMonitorItemContent(CanvasItem item,ISystemMetricsService service){this.item=item;this.service=service;panel.Children.Add(header);foreach(var r in metrics)panel.Children.Add(r.View);panel.Children.Add(divider);panel.Children.Add(down.View);panel.Children.Add(up.View);root.Child=panel;root.SizeChanged+=(_,__)=>Layout();Update(service.Snapshot);}
 public UIElement View=>root;public void SetActive(bool value){if(active==value)return;active=value;if(value){lease=service.Acquire();service.SnapshotChanged+=Changed;Update(service.Snapshot);}else{service.SnapshotChanged-=Changed;lease?.Dispose();lease=null;}}public void Dispose()=>SetActive(false);private void Changed(object? _,SystemMetricsSnapshot s)=>root.Dispatcher.BeginInvoke(()=>Update(s));
 private void Update(SystemMetricsSnapshot s){var p=WidgetTheme.Resolve(item);WidgetTheme.Apply(root,p);root.Effect=null;header.Foreground=new SolidColorBrush(p.Muted);divider.Background=new SolidColorBrush(Color.FromArgb(55,p.Foreground.R,p.Foreground.G,p.Foreground.B));metrics[0].Set(s.Cpu,ProcessorClock.Read(),p,Color.FromRgb(105,188,255));metrics[1].Set(s.Memory,Aux(s.Memory),p,Color.FromRgb(111,219,174));metrics[2].Set(s.Gpu,Aux(s.Gpu),p,Color.FromRgb(195,145,255));down.Set(s.Download,"↓  DOWN",p,Color.FromRgb(105,188,255));up.Set(s.Upload,"↑  UP",p,Color.FromRgb(255,116,116));metrics[0].View.Visibility=item.SystemMonitor.ShowCpu?Visibility.Visible:Visibility.Collapsed;metrics[1].View.Visibility=item.SystemMonitor.ShowMemory?Visibility.Visible:Visibility.Collapsed;metrics[2].View.Visibility=item.SystemMonitor.ShowGpu?Visibility.Visible:Visibility.Collapsed;down.View.Visibility=up.View.Visibility=item.SystemMonitor.ShowNetwork?Visibility.Visible:Visibility.Collapsed;divider.Visibility=(metrics.Any(r=>r.View.Visibility==Visibility.Visible)&&down.View.Visibility==Visibility.Visible)?Visibility.Visible:Visibility.Collapsed;if(initial){initial=false;NaturalHeight();}Layout();}
 private void NaturalHeight(){var rows=metrics.Count(r=>r.View.Visibility==Visibility.Visible)+(down.View.Visibility==Visibility.Visible?2:0);var next=Math.Max(96,32+rows*52+(divider.Visibility==Visibility.Visible?12:0));if(Math.Abs(item.Height-next)>.5){var top=item.CenterY-item.Height/2;item.Height=next;item.CenterY=top+next/2;}}
 private void Layout(){var width=Math.Max(96,root.ActualWidth>0?root.ActualWidth:item.Width);var height=Math.Max(96,root.ActualHeight>0?root.ActualHeight:item.Height);var visible=metrics.Where(r=>r.View.Visibility==Visibility.Visible).ToArray();var network=down.View.Visibility==Visibility.Visible;var count=visible.Length+(network?2:0);var pad=Math.Clamp(width*.045,6,14);var headerH=Math.Clamp(height*.14,18,30);var dividerH=divider.Visibility==Visibility.Visible?Math.Clamp(height*.045,7,12):0;var rowH=Math.Max(24,(height-headerH-dividerH-pad*2)/Math.Max(1,count));header.FontSize=Math.Clamp(width/31,9,12);header.Margin=new Thickness(pad,pad,0,0);header.Width=width-pad*2;header.Height=headerH;foreach(var r in metrics.Concat([down,up]))r.View.Width=width-pad*2;r.View.Margin=new Thickness(pad,0,pad,0);var y=pad+headerH;foreach(var r in visible){r.Place(y,rowH,width-pad*2);y+=rowH;}divider.Margin=new Thickness(pad,y,width-pad,0);divider.Width=width-pad*2;divider.Height=dividerH;y+=dividerH;if(network){down.Place(y,rowH,width-pad*2);y+=rowH;up.Place(y,rowH,width-pad*2);}}
 private static string Aux(MetricValue v){var i=v.Text.IndexOf("  ",StringComparison.Ordinal);return v.Availability==MetricAvailability.Available?(i>=0?v.Text[(i+2)..]:v.Text):v.Availability==MetricAvailability.Loading?"…":"--";}
 private sealed class Row{private readonly TextBlock name=new(){VerticalAlignment=VerticalAlignment.Center},value=new(){VerticalAlignment=VerticalAlignment.Center,TextAlignment=TextAlignment.Center,FontWeight=FontWeights.SemiBold},aux=new(){VerticalAlignment=VerticalAlignment.Center,TextTrimming=TextTrimming.CharacterEllipsis};private readonly Ellipse ring=new(){StrokeThickness=4};private readonly Path arc=new(){StrokeThickness=4,StrokeStartLineCap=PenLineCap.Round};internal Grid View{get;}internal Row(string title){name.Text=title;View=new Grid();View.Children.Add(name);View.Children.Add(ring);View.Children.Add(arc);View.Children.Add(value);View.Children.Add(aux);}internal void Set(MetricValue m,string extra,WidgetPalette p,Color color){name.Foreground=aux.Foreground=new SolidColorBrush(p.Muted);value.Foreground=new SolidColorBrush(p.Foreground);ring.Stroke=new SolidColorBrush(Color.FromArgb(48,p.Foreground.R,p.Foreground.G,p.Foreground.B));arc.Stroke=new SolidColorBrush(color);value.Text=m.Availability==MetricAvailability.Available?$"{m.Value:0}%":m.Availability==MetricAvailability.Loading?"…":"--";aux.Text=extra;arc.Data=Arc(m.Value??0);}internal void Place(double y,double h,double w){View.Height=h;View.Margin=new Thickness(View.Margin.Left,y,View.Margin.Right,0);var d=Math.Clamp(Math.Min(h-6,w*.22),20,58);ring.Width=ring.Height=d;arc.Width=arc.Height=d;name.FontSize=Math.Clamp(h*.29,9,14);value.FontSize=Math.Clamp(d*.25,9,14);aux.FontSize=Math.Clamp(h*.25,8,12);ring.HorizontalAlignment=arc.HorizontalAlignment=value.HorizontalAlignment=HorizontalAlignment.Center;ring.VerticalAlignment=arc.VerticalAlignment=value.VerticalAlignment=VerticalAlignment.Center;name.Margin=new Thickness(0,0,d+12,0);aux.Margin=new Thickness(d+12,0,0,0);}private static Geometry Arc(double v){if(v<=0)return Geometry.Empty;var a=Math.Min(359.9,v*3.6)*Math.PI/180;const double r=30;var e=new Point(30+r*Math.Sin(a),30-r*Math.Cos(a));return new PathGeometry([new PathFigure{StartPoint=new Point(30,0),Segments={new ArcSegment(e,new Size(r,r),a>Math.PI,false,SweepDirection.Clockwise,true)}}]);}}
}
